custom_css:
/* - - - - - - - - - - - - - - - - -

   "Black Orange"
   Graphite black with bright amber emphasis

   - - - - - - - - - - - - - - - - - */

:root {
    --customThemeColor-primary: rgba(255, 191, 0, 1);
    --customThemeColor-secondary: rgba(255, 214, 80, 1);
    --customThemeColor-soft: rgba(255, 191, 0, 0.18);
    --customThemeInk: rgba(37, 37, 37, 1);
    --customThemeSurface: rgba(43, 43, 43, 0.96);
    --customThemeSurfaceRaised: rgba(49, 49, 49, 0.98);
    --customThemeSurfaceDeep: rgba(31, 31, 31, 0.98);
    --customTopBarColor: rgba(37, 37, 37, 0.98);
    --Drawer-iconColor: var(--customThemeColor-primary);
    --sheldBackgroundColor: rgba(37, 37, 37, 0);
    --custom-avatar: calc(var(--avatar-base-width) * 0.8);
    --customThemeMenuColor: var(--SmartThemeChatTintColor);
    --active: var(--customThemeColor-primary);
    --SmartThemeCheckboxTickColor: var(--customThemeInk);
    --fullred: rgb(229, 57, 53);
    --crimson70a: rgb(229, 57, 53);
    --white30a: rgba(47, 47, 47, 0.92);
    --white50a: var(--customThemeColor-primary);
    --white70a: var(--customThemeColor-primary);
    --black30a: rgba(37, 37, 37, 0.38);
    --black50a: rgba(37, 37, 37, 0.58);
    --cobalt30a: rgba(37, 37, 37, 0.38);
    --okGreen70a: rgba(255, 191, 0, 0.78);
    --warning: var(--customThemeColor-primary);
    --golden: var(--customThemeColor-primary);
    --sb-accent: var(--SmartThemeQuoteColor);
    --sb-accent-soft: var(--SmartThemeUnderlineColor);
    --color-primary: var(--SmartThemeQuoteColor);
    --color-accent: var(--SmartThemeUnderlineColor);
    --color-background: var(--SmartThemeBlurTintColor);
    --color-surface: color-mix(in srgb, var(--SmartThemeBlurTintColor) 94%, var(--SmartThemeBodyColor) 6%);
    --color-surface-strong: color-mix(in srgb, var(--SmartThemeBlurTintColor) 88%, var(--SmartThemeBodyColor) 12%);
    --color-surface-hover: color-mix(in srgb, var(--customThemeColor-primary) 10%, var(--color-surface-strong));
    --sb-accent-ink: var(--customThemeColor-primary);
    --sb-accent-soft-ink: color-mix(in srgb, var(--customThemeColor-primary) 82%, var(--SmartThemeBodyColor) 18%);
    --sb-on-accent: rgb(37, 37, 37);
    --sb-on-solid-accent: rgb(37, 37, 37);
    --sb-shell-surface: color-mix(in srgb, var(--SmartThemeBlurTintColor) 97%, transparent);
    --sb-shell-main-bg: color-mix(in srgb, var(--SmartThemeBlurTintColor) 95%, transparent);
    --sb-shell-nav-bg: color-mix(in srgb, var(--SmartThemeBlurTintColor) 90%, var(--customThemeColor-primary) 4%);
    --sb-shell-header-bg: color-mix(in srgb, var(--SmartThemeBlurTintColor) 92%, var(--customThemeColor-primary) 4%);
    --sb-shell-header-glow: color-mix(in srgb, var(--customThemeColor-primary) 18%, transparent);
    --sb-shell-tab-active-bg: color-mix(in srgb, var(--customThemeColor-primary) 18%, var(--SmartThemeBlurTintColor) 82%);
    --sb-shell-border: color-mix(in srgb, var(--customThemeColor-primary) 48%, transparent);
    --sb-shell-shadow: 0 32px 90px color-mix(in srgb, var(--customThemeColor-primary) 18%, transparent);
    --sb-button-bg: color-mix(in srgb, var(--SmartThemeBlurTintColor) 84%, var(--customThemeColor-primary) 4%);
    --sb-button-hover: color-mix(in srgb, var(--customThemeColor-primary) 18%, var(--SmartThemeBlurTintColor) 82%);
    --sb-input-bg: color-mix(in srgb, var(--SmartThemeBlurTintColor) 90%, var(--SmartThemeBodyColor) 4%);
    --sb-input-border: color-mix(in srgb, var(--customThemeColor-primary) 44%, transparent);
    --sb-focus-ring: color-mix(in srgb, var(--customThemeColor-primary) 86%, transparent);
    --sb-state-active-bg: color-mix(in srgb, var(--customThemeColor-primary) 20%, var(--sb-button-bg));
    --sb-state-active-border: color-mix(in srgb, var(--customThemeColor-primary) 68%, var(--sb-shell-border));
    --sb-state-active-shadow: color-mix(in srgb, var(--customThemeColor-primary) 34%, transparent);
    --sb-ambient-a: color-mix(in srgb, var(--customThemeColor-primary) 14%, transparent);
    --sb-ambient-b: color-mix(in srgb, var(--customThemeColor-primary) 8%, transparent);
}

a,
code {
    color: var(--customThemeColor-primary);
}

a:hover {
    color: var(--customThemeColor-secondary);
}

::selection {
    background-color: var(--customThemeColor-primary);
    color: var(--customThemeInk);
}

h1,
h2,
h3 {
    color: color-mix(in srgb, var(--customThemeColor-primary) 84%, var(--SmartThemeBodyColor) 16%);
}

h3 {
    border-bottom: 1px solid color-mix(in srgb, var(--customThemeColor-primary) 44%, transparent);
}

.lastInContext {
    border-top: 2px dotted color-mix(in srgb, var(--customThemeColor-primary) 72%, transparent) !important;
}

#chat .mes[is_user="true"] .name_text {
    color: var(--customThemeColor-primary) !important;
}

#chat .mes[is_user="true"] .avatar {
    border: 1px solid var(--customThemeColor-primary) !important;
    box-shadow: 0 0 0 2px color-mix(in srgb, var(--customThemeColor-primary) 14%, transparent);
}

.drawer-icon {
    color: var(--Drawer-iconColor) !important;
    text-shadow: 0 0 8px color-mix(in srgb, var(--customThemeColor-primary) 42%, transparent);
}

.openIcon .drawer-icon,
.drawer-icon.openIcon {
    color: var(--customThemeColor-secondary) !important;
}

blockquote {
    border-inline-start: 1px solid color-mix(in srgb, var(--customThemeColor-primary) 70%, transparent);
    color: color-mix(in srgb, var(--customThemeColor-primary) 84%, var(--SmartThemeBodyColor) 16%);
    background: color-mix(in srgb, var(--customThemeColor-primary) 8%, transparent);
}

.menu_button:hover,
.menu_button:focus-visible {
    border-color: color-mix(in srgb, var(--customThemeColor-primary) 58%, var(--SmartThemeBorderColor));
    box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--customThemeColor-primary) 32%, transparent);
}

.menu_button.menu_button_primary,
.popup-button-ok {
    background: var(--customThemeColor-primary) !important;
    color: var(--customThemeInk) !important;
    border-color: var(--customThemeColor-primary) !important;
}

input:focus,
textarea:focus,
select:focus {
    border-color: var(--customThemeColor-primary) !important;
    box-shadow: 0 0 0 2px color-mix(in srgb, var(--customThemeColor-primary) 38%, transparent) !important;
}

input[type="checkbox"]:checked,
input[type="range"] {
    accent-color: var(--customThemeColor-primary);
}

.swipe_left,
.swipe_right {
    color: var(--customThemeColor-primary) !important;
}

::-webkit-scrollbar-thumb {
    background-color: color-mix(in srgb, var(--customThemeColor-primary) 68%, var(--SmartThemeBlurTintColor)) !important;
}

::-webkit-scrollbar-thumb:hover {
    background-color: var(--customThemeColor-primary) !important;
}

* {
    scrollbar-color: color-mix(in srgb, var(--customThemeColor-primary) 68%, var(--SmartThemeBlurTintColor)) transparent;
}

.sb-accent-preset[data-accent="orange"] {
    --sb-accent-swatch: #FFBF00;
}
